import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {TextDecoder, types} from 'node:util';

export function createDecoder() {
  // Streaming decoding preserves split code points and removes only the first BOM.
  const utf8 = new TextDecoder('utf-8', {fatal: true});
  let pendingLine = '';
  let data = [];
  let event = null;
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function acceptText(text) {
    const frames = [];
    const buffered = pendingLine + text;
    let start = 0;
    let end;
    while ((end = buffered.indexOf('\n', start)) !== -1) {
      let line = buffered.slice(start, end);
      start = end + 1;
      if (line.endsWith('\r')) line = line.slice(0, -1);

      if (terminated) {
        if (line !== '') throw Error('Nonblank line after termination');
        continue;
      }
      if (line === '') {
        if (data.length > 0) {
          const value = data.join('\n');
          if (value === '[DONE]') terminated = true;
          else frames.push({event: event || 'message', data: value});
        }
        data = [];
        event = null;
        continue;
      }
      if (line.startsWith(':')) continue;
      const colon = line.indexOf(':');
      const field = colon === -1 ? line : line.slice(0, colon);
      let value = colon === -1 ? '' : line.slice(colon + 1);
      if (value.startsWith(' ')) value = value.slice(1);
      if (field === 'data') data.push(value);
      else if (field === 'event') event = value;
    }
    pendingLine = buffered.slice(start);
    return frames;
  }

  function guard(action) {
    try {
      if (poisoned || finished) throw Error('Decoder is no longer usable');
      return action();
    } catch (error) {
      poisoned = true;
      throw error;
    }
  }

  return {
    push(chunk) {
      return guard(() => {
        if (!types.isUint8Array(chunk)) throw Error('Chunk must be a Uint8Array');
        return acceptText(utf8.decode(chunk, {stream: true}));
      });
    },
    finish() {
      return guard(() => {
        acceptText(utf8.decode());
        if (pendingLine !== '') throw Error('Unterminated final line');
        if (!terminated || data.length > 0 || event !== null) {
          throw Error('Stream has not completed');
        }
        finished = true;
        return [];
      });
    },
  };
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{
    if(process.argv.length!==3)throw Error('usage: stream-framer.js INPUT_JSON_FILE');
    const input=JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(fs.readFileSync(process.argv[2])));
    if(input===null||typeof input!=='object'||Array.isArray(input)||!Array.isArray(input.chunks)){
      throw Error('Input must be an object with a chunks array');
    }
    const decoder=createDecoder(),frames=[];
    for(const encoded of input.chunks){
      if(typeof encoded!=='string')throw Error('Chunks must be base64 strings');
      const chunk=Buffer.from(encoded,'base64');
      if(chunk.toString('base64')!==encoded)throw Error('Noncanonical base64');
      for(const frame of decoder.push(chunk))frames.push(frame);
    }
    decoder.finish();process.stdout.write(JSON.stringify({frames})+'\n');
  }catch(error){process.stderr.write(String(error.message)+'\n');process.exitCode=2;}
}

