import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

const done = Buffer.from('data: [DONE]\n\n');

test('every two-part split and fixed chunk size preserves protocol values', () => {
  const bytes = Buffer.from('\uFEFFevent: discarded\nunknown: x\n\n' +
    ': comment\nevent: old\nevent: delta\r\ndata:  雪😀\r\n' +
    'data: a\rb\r\r\ndata:\ndata: \uFEFFtail\r\n\r\n' +
    'event: old\nevent\ndata\n\nData: ignored\n\n' +
    'event: ignored\ndata: [DONE]\n\n\r\n\n');
  const expected = [
    {event: 'delta', data: ' 雪😀\na\rb\r\n\n\uFEFFtail'},
    {event: 'message', data: ''},
  ];
  function check(chunks) {
    const decoder = createDecoder();
    const frames = [];
    for (const chunk of chunks) {
      const original = Buffer.from(chunk);
      frames.push(...decoder.push(chunk));
      assert.deepEqual(chunk, original);
      assert.deepEqual(decoder.push(new Uint8Array()), []);
    }
    assert.deepEqual(decoder.finish(), []);
    assert.deepEqual(frames, expected);
  }
  for (let split = 0; split <= bytes.length; split++) {
    check([bytes.subarray(0, split), bytes.subarray(split)]);
  }
  for (let size = 1; size <= bytes.length; size++) {
    const chunks = [];
    for (let i = 0; i < bytes.length; i += size) chunks.push(bytes.subarray(i, i + size));
    check(chunks);
  }
});

function assertPoisoned(decoder) {
  assert.throws(() => decoder.push(new Uint8Array()), Error);
  assert.throws(() => decoder.push(done), Error);
  assert.throws(() => decoder.finish(), Error);
}

test('bad chunk types poison only their decoder', () => {
  for (const chunk of ['', null, undefined, [], {}, new ArrayBuffer(0),
    new Uint8ClampedArray(), new Uint16Array(), new DataView(new ArrayBuffer(0))]) {
    const decoder = createDecoder();
    assert.throws(() => decoder.push(chunk), Error);
    assertPoisoned(decoder);
  }
  const decoder = createDecoder();
  decoder.push(done);
  assert.deepEqual(decoder.finish(), []);
  assert.throws(() => decoder.finish(), Error);
  assertPoisoned(decoder);
});

test('strict UTF-8 rejects malformed and unfinished sequences', () => {
  for (const bytes of [[0x80], [0xc0, 0xaf], [0xed, 0xa0, 0x80],
    [0xf4, 0x90, 0x80, 0x80], [0xe2, 0x28, 0xa1]]) {
    for (const split of [false, true]) {
      const decoder = createDecoder();
      assert.throws(() => {
        if (split) for (const byte of bytes) decoder.push(Uint8Array.of(byte));
        else decoder.push(Uint8Array.from(bytes));
      }, Error);
      assertPoisoned(decoder);
    }
  }
  for (const bytes of [[0xef], [0xef, 0xbb], [0xf0, 0x9f, 0x98]]) {
    const decoder = createDecoder();
    decoder.push(done);
    decoder.push(Uint8Array.from(bytes));
    assert.throws(() => decoder.finish(), Error);
    assertPoisoned(decoder);
  }
});

test('completion requires a dispatched marker and permits only blank trailing lines', () => {
  for (const text of ['', '\n', 'data: x\n', 'event:\n', 'data: [DONE]\n',
    'data: [DONE]', 'data: [DONE]\n\n\r', 'data: [DONE]\n\ntrailing']) {
    const decoder = createDecoder();
    decoder.push(Buffer.from(text));
    assert.throws(() => decoder.finish(), Error);
    assertPoisoned(decoder);
  }
  for (const trailing of [': comment\n', 'unknown\n', 'event:\n',
    'data: [DONE]\n\n', ' \n', '\r\r\n']) {
    const decoder = createDecoder();
    const earlier = decoder.push(Buffer.from('data: earlier\n\n'));
    assert.throws(() => decoder.push(Buffer.from('data: later\n\n' + done.toString() + trailing)), Error);
    assert.deepEqual(earlier, [{event: 'message', data: 'earlier'}]);
    assertPoisoned(decoder);
  }
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(Buffer.from('data: [DONE]\ndata:\n\ndata:  [DONE]\n\n' + done)), [
    {event: 'message', data: '[DONE]\n'}, {event: 'message', data: ' [DONE]'},
  ]);
  decoder.finish();
});

test('CLI validates arguments, input, canonical base64 and protocol without partial stdout', () => {
  const directory = mkdtempSync(join(tmpdir(), 'stream-framer-'));
  const file = join(directory, 'input.json');
  const script = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
  function run(args = [file]) {
    return spawnSync(process.execPath, [script, ...args], {encoding: 'utf8'});
  }
  function failed(result) {
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  }
  try {
    const bytes = Buffer.from('\uFEFFdata: 雪😀\n\n' + done);
    writeFileSync(file, JSON.stringify({extra: true, chunks: ['', ...Array.from(bytes, b => Buffer.from([b]).toString('base64'))]}));
    const success = run();
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"frames":[{"event":"message","data":"雪😀"}]}\n');
    failed(run([]));
    failed(run([file, file]));
    failed(run([join(directory, 'missing')]));
    for (const input of [null, [], 1, 'x', {}, {chunks: ''}, {chunks: []},
      ...[null, 1, 'Zg', 'Zg=', 'Zh==', 'Zm9=', 'Zg===', ' Zg==', 'Zg==\n', '-w==', '_w==', '===='].map(value => ({chunks: [value]})),
      {chunks: [Buffer.from('data: visible\n\n').toString('base64')]},
      {chunks: [done.toString('base64'), Buffer.from(': invalid\n').toString('base64')]}]) {
      writeFileSync(file, JSON.stringify(input));
      failed(run());
    }
    for (const contents of ['{', Buffer.from([0xff])]) {
      writeFileSync(file, contents);
      failed(run());
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `await import(${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)})`], {encoding: 'utf8'});
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, {recursive: true, force: true});
  }
});

